import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Special Attacks y acciones preparadas","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/special-attacks.md","filePath":"es/guide/combat/special-attacks.md"}'),o={name:"es/guide/combat/special-attacks.md"};function n(c,a,s,d,l,p){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="special-attacks-and-prepared-actions" tabindex="-1">Special Attacks y acciones preparadas <a class="header-anchor" href="#special-attacks-and-prepared-actions" aria-label="Enlace permanente a &quot;Special Attacks y acciones preparadas&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Experimental: repertorio preparado · No implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Aprende Special Attacks (SA, ataques especiales) con maestros, manuales, exploración y desafíos.</li><li>Las técnicas aprendidas se conservan; prepara un repertorio pequeño para usarlo de inmediato.</li><li>Familiarity (fluidez práctica) mejora modestamente la ejecución; el momento y el enfrentamiento siguen determinando la utilidad de una acción.</li></ul><p><span id="at-a-glance"></span><span id="first-weapon-kits"></span><span id="trade-offs"></span><span id="preparation"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspecto</th><th>Significado</th></tr></thead><tbody><tr><td>Preparación</td><td>Una técnica debe estar aprendida, preparada y ser compatible con tu arma; los ataques básicos no ocupan espacios del repertorio.</td></tr><tr><td>Ataque</td><td>Pon un golpe válido en cola en Legacy; inicia una acción disponible en Modern.</td></tr><tr><td>Defensa</td><td>Brace y Riposte son respuestas manuales con límites de momento, resistencia y compatibilidad.</td></tr><tr><td>Cambiar el repertorio</td><td>Prepáralo fuera del combate activo tras un intervalo tranquilo; cambiarlo no cancela la recuperación. INT no es un requisito obligatorio para obtener espacios marciales.</td></tr></tbody></table><p>Aprender un SA no garantiza acertar. El conocimiento persiste, aunque la fluidez práctica puede disminuir por falta de uso. La capacidad final del repertorio y las futuras interacciones con INT siguen sin resolver.</p><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Syrolands</th></tr></thead><tbody><tr><td>UOR ya incluía ataques especiales</td><td>Convertir las técnicas en conocimiento aprendido, con repertorio preparado y Familiarity.</td></tr><tr><td>El UO posterior asigna movimientos primarios y secundarios a las armas</td><td>Separar conocer una técnica de prepararla y ejecutarla con equipo compatible.</td></tr></tbody></table><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Preparas Brace para responder a un ataque pesado y comprometido. El rival usa Feint: tu defensa consume tiempo y resistencia sin recibir el golpe esperado.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Modos</a> · <a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/actions.html">Leer la especificación de diseño completa</a></p>',16)])])}const h=e(o,[["render",n]]);export{m as __pageData,h as default};
